            try kvNormRope(t, c.ptr("Y"), c.ptr("W"), c.ptr("COS"), c.ptr("SIN"), c.ptr("POS"), c.ptr("RING"), c.dim("RING", 0), c.ptr("SLOT_OF"), c.float("eps"), quant, rd, c.ptr("OUT"), c.dim("Y", 0), c.dim("Y", 1));
        }
    }.call);
